"""建立人工标注题库；只写当前目录。"""
import json,hashlib,re
from pathlib import Path
from PIL import Image
BASE=Path(__file__).resolve().parent
rows=[]
def add(id,split,scene,nearest,ground,text,uncertain,short,q1,a1,q2,a2,trap=2,tags=()):
 source=('clean5/'+id[2:]+'.jpg') if id.startswith('C_') else ('frames/'+id.replace('_','/',1)+'.jpg')
 p=BASE/source;im=Image.open(p);rotate=im.width>im.height
 if rotate: im=im.transpose(Image.Transpose.ROTATE_270)
 crop=32 if id.startswith('lab_') else 0
 # clean5 已经裁过 32 像素；源视频帧没有黄色叠字，不裁真实内容。
 im=im.crop((0,crop,im.width,im.height));out='images/'+id+'.jpg';im.save(BASE/out,quality=95)
 questions=[{'id':'描述','mode':'短按','text':'描述眼前。','trap':False,'expected':short},{'id':'问题一','mode':'长按','text':'简短回答盲人的问题：'+q1,'trap':trap==1,'expected':a1},{'id':'问题二','mode':'长按','text':'简短回答盲人的问题：'+q2,'trap':trap==2,'expected':a2}]
 rows.append(dict(id=id,source=source,image=out,split=split,scene=scene,tags=list(tags),preprocess={'顺时针旋转90度':rotate,'顶部裁剪像素':crop,'尺寸':list(im.size),'sha256':hashlib.sha256((BASE/out).read_bytes()).hexdigest()},truth={'最近物体':nearest,'路面':ground,'文字':text,'不确定':uncertain},tasks=questions))
